:root
{    
    --activeLineGlyphCursor: grab;
    --activeLineGlyphTransform: none;

    --generalScaling: 1;
    --ide-fontsize: 13px;
    --timestampsDisplay: none;

    aaacolor-scheme: dark;
}

html, body 
{
    position: absolute;
    left: 0;
    top: 0;
    width: 100%;
    height: 100%;
    margin: 0;
    padding: 0;
    overflow: hidden;
    font-family: 'Segoe WPC','Segoe UI',sans-serif;
    font-size: var(--ide-fontsize);
    box-sizing: border-box;
    touch-action: none;
    cursor: default;
    -webkit-user-select: none;
    overscroll-behavior-x: none;
    overscroll-behavior-y: none;
}

.Unfocused
{
    -webkit-filter: grayscale(0.75);   
    transition: filter 2s ease; 
}

body
{
    background-color: var(--themeGeneralBackColor);
}

