    color: var(--themeGeneralTextColor);
    font-family: monospace;
    flex-grow: 1;
    padding: 3px;
    white-space: pre-wrap;

    flex-direction: column;
    display: grid;
    grid-template-columns: max-content auto max-content;
    grid-template-rows: min-content;
    row-gap: 2px;
    padding: 4px;
    flex-grow: 0;
}

.packageManagerFullLine
{
    color: grey;
    text-align: center;
    padding: 2px;
}

.packageManagerPublish
{
    border: 1px solid white;
    color: white;
    font-size: 120%;
    font-weight: bold;
    background-color: #790000;
    border-radius: 10px;
    text-align: center;
    margin: 10px;
    padding: 2px;
    padding-bottom: 4px;
}

.packageManagerPublish:hover
{
    background-color: #c44545;
}

.packageManagerRow
{
    display: contents;
}

.packageManagerRow:hover > div
{
    background-color: var(--themePackageManagerHoverBackColor);
}

.packageManagerRow > div
{
    padding-top: 5px;
    padding-bottom: 5px;
    padding-left: 10px;
    padding-right: 10px;
    border-radius: 2px;
}

.packageManagerHeader
{
    border-right: 1px solid rgba(128, 128, 128, 0.128);
    color: grey;
}

.packageManagerData
{
    border-right: 1px solid rgba(128, 128, 128, 0.128);
}

.packageManagerLink
{
    text-align: right;
    color: #41a3c2;
    text-decoration: underline;
}

.sectionRootHidden, .sectionHeaderHidden
{
    adisplay: none !important;
    opacity: 0.4;
    pointer-events: none;
    -webkit-filter: grayscale(1);
}

.sectionRootNone
{
    max-height: 0;
}

.columnReverse
{
    flex-direction: column-reverse !important;
}

.debugConsoleOutput2, .traceOutputOutput2
{
    flex-grow: 1;
    position: relative;
    overflow: hidden;
    color: var(--themeGeneralTextColor);
    font-family: monospace;
    white-space: pre-wrap;
}

.debugConsoleOutput2 .listItems div, .traceOutputOutput2 .listItems div
{
    padding: 2px 0px;
    cursor: text;
    user-select: text;
}


.debugConsoleOutput, .traceOutputOutput
{
    color: var(--themeGeneralTextColor);
    font-family: monospace;
    flex-grow: 1;
    padding: 3px;
    overflow-y: scroll;
    white-space: pre-wrap;

    flex-direction: column;
    display: flex;
}

.debugConsoleOutput div, .traceOutputOutput div
{
    padding: 2px 0px;
    cursor: text;
    user-select: text;
    display: flex;
}

.debugConsoleOutput div:hover, .traceOutputOutput div:hover
{
    background-color:rgb(109, 108, 108, 0.3);
}

.debugConsoleOutput div:empty:before, .traceOutputOutput div:empty:before
{
    content: '\a0';
}

.debugConsoleEntryContainer
{
    display: flex;
    flex-direction: row;
    width: 100%;
    border-top: 1px solid grey;
    align-items: center;
    padding-top: 2px;
    padding-bottom: 2px;
    background-color: #a6878740;
    margin-top: 1px;
}

.debugConsoleEntryMarker
{
    color: var(--themeGeneralTextColor);
    font-weight:900;
    flex-basis: 20px;
    font-family: monospace;
    text-align: center;
}    

.debugConsoleEntry
{
    flex-grow: 1;
    outline: 0;
    border: 0;
    background-color: transparent;
    color: var(--themeGeneralTextColor);
    font-family: monospace;
}

.stackFrameProc
{
    flex-grow: 1;
    padding-right: 7px;
    font-size: 90%;
    font-weight: 400;
    text-overflow: ellipsis;
    overflow: hidden;
}

.stackFrameFile
{
    padding-right: 7px;
    overflow-x: hidden;
    text-overflow: ellipsis;
    font-size: 90%;
    font-weight: normal;
    color: #868484;
}

.stackFrameLineCol
{
    padding-right: 8px;
    flex-shrink: 0;
    font-size: 90%;
    font-weight: normal;
}

.folderDropZone
{
    background-color: rgba(163, 64, 64, 0.664) !important;
}

.tabDropZoneLeft::before
{
    width: 6px;
    height: 100%;
    position: absolute;
    content: "";
    background-color: rgb(223, 90, 90) !important;
    padding: -10px;
    left: -3px;
}
.tabDropZoneRight::after
{
    width: 6px;
    height: 100%;
    position: absolute;
    content: "";
    background-color: rgb(223, 90, 90) !important;
    padding: -10px;
    right: -5px;
