.middlePanelHorizontal
{
    border-bottom: 1px solid black;
    flex-direction: row;
}

.middlePanelResizer
{
    position: absolute;
    z-index: 1;
    width: 6px;
    height: 100%;
    right: 0;
    opacity: 0;
}

.middlePanelResizerHorizontal
{
    position: absolute;
    z-index: 1;
    height: 6px;
    width: 100%;
    bottom: 0;
    opacity: 0;
}

.middlePanelResizer:hover, .middlePanelResizerHorizontal:hover
{
    animation: draggableBlueEaseIn 1s ease-in forwards;
}

.middlePanelResizer:hover, .middlePanelResizerHorizontal:hover
{
    opacity: 1;    
    cursor: w-resize;
}

.middlePanelResizerHorizontal:hover
{
    cursor: n-resize;
}

#leftPanelResizer
{
    position: absolute;
    z-index: 1;
    width: 6px;
    height: 100%;
    right: 0;
    opacity: 0;
}

#leftPanelResizer:hover
{
    animation: draggableBlueEaseIn 1s ease-in forwards;
}

@-webkit-keyframes draggableBlueEaseIn {
    to {
        background-color: #468efb;
    }
  }

#leftPanelResizer:hover
{
    opacity: 1;    
    cursor: w-resize;
}

#centerPanelResizer
{
    position: absolute;
