.dockGroupVerticalDockPointTop
{
    height: 6px;
    position: absolute;
    width: 100%;
    z-index: 999;
    top: -1;
}
.dockGroupVerticalDockPointBottom
{
    height: 6px;
    position: absolute;
    width: 100%;
    z-index: 999;
    bottom: 0px;
}

.dockGroupVerticalDockPointTopHover, .dockGroupVerticalDockPointBottomHover
{
    height: 30px;
    animation: zIndexTest 2s ease-in forwards;
}

/* this delay change of x-index helps when there are nested groups, allowing the user to select the outer group if they wait */
@-webkit-keyframes zIndexTest {
    0%, 99% {
    }

    100% {
        z-index: 998;
    }
  }


.dockGroupVertical:has(> .dockGroupVerticalDockPointTopHover) 
{
    background: repeating-linear-gradient(45deg, rgba(232, 232, 233), rgba(251, 251, 253, 0.0001) 1px, rgba(200, 200, 200, 0.0001) 1px, rgba(255, 255, 255, 0.0001) 5px);
    background-size: 100% 0px;
    background-repeat: no-repeat;
    animation: paddingTop30 0.4s ease-in forwards;
}

.dockGroupVertical:has(> .dockGroupVerticalDockPointBottomHover) 
{
    background: repeating-linear-gradient(45deg, rgba(232, 232, 233), rgba(251, 251, 253, 0.0001) 1px, rgba(200, 200, 200, 0.0001) 1px, rgba(255, 255, 255, 0.0001) 5px);
    background-size: 100% 0px;
    background-repeat: no-repeat;
    background-position-y: 100%;
    animation: paddingBottom30 0.4s ease-in forwards;
}

  @-webkit-keyframes paddingTop30 {
    to {
        padding-top: 30px;
        background-size: 100% 30px;
    }
  }

  @-webkit-keyframes paddingBottom30 {
    to {
        padding-bottom: 30px;
        background-size: 100% 30px;
    }
  }



