    animation: zIndexTest 2s ease-in forwards;
}

.dockGroupHorizontal:has(> .dockGroupHorizontalDockPointLeftHover) 
{
    background: repeating-linear-gradient(45deg, rgba(232, 232, 233), rgba(251, 251, 253, 0.0001) 1px, rgba(200, 200, 200, 0.0001) 1px, rgba(255, 255, 255, 0.0001) 5px);
    background-size: 0px 100%;
    background-repeat: no-repeat;
    animation: paddingLeft30 0.4s ease-in forwards;
}

.dockGroupHorizontal:has(> .dockGroupHorizontalDockPointRightHover) 
{
    background: repeating-linear-gradient(45deg, rgba(232, 232, 233), rgba(251, 251, 253, 0.0001) 1px, rgba(200, 200, 200, 0.0001) 1px, rgba(255, 255, 255, 0.0001) 5px);
    background-size: 0px 100%;
    background-repeat: no-repeat;
    background-position-x: 100%;
    animation: paddingRight30 0.4s ease-in forwards;
}

